/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getColor = require( './color/get.js' );
var setColor = require( './color/set.js' );

var getField = require( './field/get.js' );
var setField = require( './field/set.js' );

var getProperties = require( './properties/get.js' );

var getSignal = require( './signal/get.js' );
var setSignal = require( './signal/set.js' );

var getValue = require( './value/get.js' );
var setValue = require( './value/set.js' );


// VARIABLES //

var debug = logger( 'vega:value:main' );


// MAIN //

/**
* Value constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {string} [options.signal] - signal name or expression
* @param {Object} [options.color] - color value specifying per-channel references
* @param {(string|Object)} [options.field] - data field name or descriptor
* @param {*} [options.value] - constant value
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Value} value instance
*
* @example
* var value = new Value();
* // returns <Value>
*/
function Value( options ) {
	var nargs;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Value ) ) {
		if ( nargs ) {
			return new Value( options );
		}
		return new Value();
	}
	EventEmitter.call( this );

	// Set internal properties to undefined (no defaults per Vega spec)...
	for ( i = 0; i < properties.length; i++ ) {
		this[ '_'+properties[ i ] ] = void 0;
	}
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Value, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Value
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Value, 'name', 'Value' );

/**
* Color value specifying per-channel references.
*
* @name color
* @memberof Value.prototype
* @type {(Object|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'color': { 'r': { 'value': 255 }, 'g': { 'value': 0 }, 'b': { 'value': 0 } }
* });
*
* var c = value.color;
* // returns { 'r': { 'value': 255 }, 'g': { 'value': 0 }, 'b': { 'value': 0 } }
*/
setReadWriteAccessor( Value.prototype, 'color', getColor, setColor );

/**
* Data field name or descriptor.
*
* @name field
* @memberof Value.prototype
* @type {(string|Object|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'field': 'price'
* });
*
* var v = value.field;
* // returns 'price'
*/
setReadWriteAccessor( Value.prototype, 'field', getField, setField );

/**
* Value properties.
*
* @name properties
* @memberof Value.prototype
* @type {Array<string>}
*
* @example
* var value = new Value();
*
* var v = value.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Value.prototype, 'properties', getProperties );

/**
* Signal name or expression.
*
* @name signal
* @memberof Value.prototype
* @type {(string|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'signal': 'width'
* });
*
* var v = value.signal;
* // returns 'width'
*/
setReadWriteAccessor( Value.prototype, 'signal', getSignal, setSignal );

/**
* Constant value.
*
* @name value
* @memberof Value.prototype
* @type {*}
* @default undefined
*
* @example
* var value = new Value({
*     'value': 5
* });
*
* var v = value.value;
* // returns 5
*/
setReadWriteAccessor( Value.prototype, 'value', getValue, setValue );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Value.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var value = new Value({
*     'value': 5
* });
*
* var json = value.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Value.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Value;
